-- Seed datasets applied to this database (versioned, idempotent reference data).
CREATE TABLE IF NOT EXISTS "secureplus.SeedVersion" (
    "Dataset" TEXT NOT NULL,
    "Version" TEXT NOT NULL,
    "ContentHash" TEXT NOT NULL,
    "RowsApplied" INTEGER NOT NULL,
    "AppliedAtUtc" TEXT NOT NULL,
    "AppliedBy" TEXT NOT NULL,
    "Summary" TEXT,
    PRIMARY KEY ("Dataset")
);
GO
-- Solution areas and experience areas.
CREATE TABLE IF NOT EXISTS "secureplus.ReferenceValue" (
    "Category" TEXT NOT NULL,
    "Code" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "Description" TEXT,
    "SortOrder" INTEGER NOT NULL,
    PRIMARY KEY ("Category", "Code")
);
GO
-- Remediation content and implementation details of each catalog control (EaaS v3 has no columns for them).
CREATE TABLE IF NOT EXISTS "secureplus.ControlDetail" (
    "ControlId" TEXT NOT NULL,
    "SeedVersion" TEXT NOT NULL,
    "SolutionArea" TEXT,
    "ExperienceArea" TEXT,
    "VariantOf" TEXT,
    "VariantLabel" TEXT,
    "ComplianceStandards" TEXT,
    "EstimatedMinutes" INTEGER,
    "Difficulty" TEXT,
    "Effort" TEXT,
    "RiskLevel" TEXT,
    "Benefits" TEXT,
    "ExperienceImpact" TEXT,
    "GraphRequest" TEXT,
    "GraphCommand" TEXT,
    "PowerShell" TEXT,
    "JsonBody" TEXT,
    "SettingPath" TEXT,
    "GpoPath" TEXT,
    "Registry" TEXT,
    "Generated" TEXT,
    "UpdatedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("ControlId")
);
GO
CREATE INDEX IF NOT EXISTS "IX_ControlDetail_SolutionArea" ON "secureplus.ControlDetail" ("SolutionArea");
GO
-- Old control IDs of merged duplicates; results stored with an alias resolve to ControlId.
CREATE TABLE IF NOT EXISTS "secureplus.ControlAlias" (
    "Alias" TEXT NOT NULL,
    "ControlId" TEXT NOT NULL,
    "Reason" TEXT,
    PRIMARY KEY ("Alias")
);
GO
-- Run history of recurring assessment schedules.
CREATE TABLE IF NOT EXISTS "secureplus.ScheduleRun" (
    "ScheduleRunId" INTEGER PRIMARY KEY,
    "ScheduleId" INTEGER NOT NULL,
    "StartedAtUtc" TEXT NOT NULL,
    "CompletedAtUtc" TEXT,
    "StatusCode" TEXT NOT NULL,
    "Message" TEXT,
    "Host" TEXT,
    "AssessmentRunIds" TEXT,
    FOREIGN KEY ("ScheduleId") REFERENCES "secureplus.AssessmentSchedule" ("ScheduleId")
);
GO
CREATE INDEX IF NOT EXISTS "IX_ScheduleRun_Schedule" ON "secureplus.ScheduleRun" ("ScheduleId", "StartedAtUtc");
GO
-- Specifications: standard (unassigned) or tailored. Linked to spec.Specification when assigned to an engagement.
CREATE TABLE IF NOT EXISTS "secureplus.Specification" (
    "SpecificationKey" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "Description" TEXT,
    "IsStandard" INTEGER NOT NULL,
    "IsSystem" INTEGER NOT NULL,
    "IsModified" INTEGER NOT NULL,
    "BasedOnKey" TEXT,
    "StatusCode" TEXT NOT NULL,
    "SeedVersion" TEXT,
    "CreatedBy" TEXT NOT NULL,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedBy" TEXT,
    "ModifiedAtUtc" TEXT,
    PRIMARY KEY ("SpecificationKey")
);
GO
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Specification_Name" ON "secureplus.Specification" ("Name");
GO
-- Members of a specification: Experience, Framework, ComplianceStandard, Requirement, PolicySet, Control or Policy.
CREATE TABLE IF NOT EXISTS "secureplus.SpecificationItem" (
    "SpecificationKey" TEXT NOT NULL,
    "ItemType" TEXT NOT NULL,
    "ItemKey" TEXT NOT NULL,
    PRIMARY KEY ("SpecificationKey", "ItemType", "ItemKey"),
    FOREIGN KEY ("SpecificationKey") REFERENCES "secureplus.Specification" ("SpecificationKey") ON DELETE CASCADE
);
GO
-- The specification each customer uses (one per customer).
CREATE TABLE IF NOT EXISTS "secureplus.SpecificationAssignment" (
    "CustomerKey" TEXT NOT NULL,
    "SpecificationKey" TEXT NOT NULL,
    "AssignedBy" TEXT NOT NULL,
    "AssignedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("CustomerKey")
);
GO
CREATE INDEX IF NOT EXISTS "IX_SpecificationAssignment_Specification" ON "secureplus.SpecificationAssignment" ("SpecificationKey");
GO
-- Baseline configurations: named, activatable collections of policy sets and controls.
CREATE TABLE IF NOT EXISTS "secureplus.Baseline" (
    "BaselineKey" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "Description" TEXT,
    "IsActive" INTEGER NOT NULL,
    "IsSystem" INTEGER NOT NULL,
    "IsModified" INTEGER NOT NULL,
    "SeedVersion" TEXT,
    "CreatedBy" TEXT NOT NULL,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedBy" TEXT,
    "ModifiedAtUtc" TEXT,
    PRIMARY KEY ("BaselineKey")
);
GO
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Baseline_Name" ON "secureplus.Baseline" ("Name");
GO
-- Members of a baseline: Framework, ComplianceStandard, Experience, PolicySet, Control or Policy.
CREATE TABLE IF NOT EXISTS "secureplus.BaselineItem" (
    "BaselineKey" TEXT NOT NULL,
    "ItemType" TEXT NOT NULL,
    "ItemKey" TEXT NOT NULL,
    PRIMARY KEY ("BaselineKey", "ItemType", "ItemKey"),
    FOREIGN KEY ("BaselineKey") REFERENCES "secureplus.Baseline" ("BaselineKey") ON DELETE CASCADE
);
GO
-- Change requests (extends deploy.ChangeRequest with risk, rollback, approval, window and workflow status).
CREATE TABLE IF NOT EXISTS "secureplus.ChangeRequest" (
    "ChangeRequestId" INTEGER PRIMARY KEY,
    "CustomerKey" TEXT NOT NULL,
    "Title" TEXT NOT NULL,
    "Description" TEXT,
    "Risk" TEXT NOT NULL,
    "Impact" TEXT,
    "RollbackPlan" TEXT,
    "RequestedBy" TEXT NOT NULL,
    "ApprovedBy" TEXT,
    "Owner" TEXT,
    "WindowStartUtc" TEXT,
    "WindowEndUtc" TEXT,
    "StatusCode" TEXT NOT NULL,
    "DecisionNote" TEXT,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedAtUtc" TEXT NOT NULL,
    "DecidedAtUtc" TEXT,
    "CompletedAtUtc" TEXT
);
GO
CREATE INDEX IF NOT EXISTS "IX_ChangeRequest_Customer" ON "secureplus.ChangeRequest" ("CustomerKey", "StatusCode");
GO
-- Controls and policies changed by a change request.
CREATE TABLE IF NOT EXISTS "secureplus.ChangeRequestItem" (
    "ChangeRequestId" INTEGER NOT NULL,
    "ItemType" TEXT NOT NULL,
    "ItemKey" TEXT NOT NULL,
    PRIMARY KEY ("ChangeRequestId", "ItemType", "ItemKey"),
    FOREIGN KEY ("ChangeRequestId") REFERENCES "secureplus.ChangeRequest" ("ChangeRequestId") ON DELETE CASCADE
);
GO
-- Executions and simulations of approved change requests.
CREATE TABLE IF NOT EXISTS "secureplus.ChangeExecution" (
    "ChangeExecutionId" INTEGER PRIMARY KEY,
    "ChangeRequestId" INTEGER NOT NULL,
    "ModeCode" TEXT NOT NULL,
    "StatusCode" TEXT NOT NULL,
    "StartedAtUtc" TEXT NOT NULL,
    "CompletedAtUtc" TEXT,
    "ExecutedBy" TEXT NOT NULL,
    "Log" TEXT,
    "ReassessmentRunId" INTEGER,
    FOREIGN KEY ("ChangeRequestId") REFERENCES "secureplus.ChangeRequest" ("ChangeRequestId")
);
GO
CREATE INDEX IF NOT EXISTS "IX_ChangeExecution_Request" ON "secureplus.ChangeExecution" ("ChangeRequestId");
GO
-- Approved exceptions: a control a customer is not required to meet, with reason, approver and expiry.
CREATE TABLE IF NOT EXISTS "secureplus.CustomerException" (
    "ExceptionId" INTEGER PRIMARY KEY,
